class Solution:
    def shortestCompletingWord(self, licensePlate: str, words: List[str]) -> str:
        def counts(s):
            c = [0] * 26
            for ch in s:
                if ch.isalpha():
                    c[ord(ch.lower()) - ord('a')] += 1
            return c
        plate = counts(licensePlate)
        ans = None
        for w in words:
            if all(counts(w)[i] >= plate[i] for i in range(26)):
                if ans is None or len(w) < len(ans):
                    ans = w
        return ans

