class Solution {
public:
    vector<int> counts(const string& s) {
        vector<int> c(26, 0);
        for (char ch : s)
            if (isalpha(ch)) c[tolower(ch) - 'a']++;
        return c;
    }
    bool covers(const vector<int>& w, const vector<int>& p) {
        for (int i = 0; i < 26; i++)
            if (w[i] < p[i]) return false;
        return true;
    }
    string shortestCompletingWord(string licensePlate, vector<string>& words) {
        auto plate = counts(licensePlate);
        string ans;
        for (auto& w : words)
            if ((ans.empty() || w.size() < ans.size()) && covers(counts(w), plate))
                ans = w;
        return ans;
    }
};

