class Solution {
    private int[] counts(String s) {
        int[] c = new int[26];
        for (char ch : s.toCharArray())
            if (Character.isLetter(ch)) c[Character.toLowerCase(ch) - 'a']++;
        return c;
    }
    public String shortestCompletingWord(String licensePlate, String[] words) {
        int[] plate = counts(licensePlate);
        String ans = null;
        for (String w : words) {
            int[] cnt = counts(w);
            boolean ok = true;
            for (int i = 0; i < 26 && ok; i++) ok = cnt[i] >= plate[i];
            if (ok && (ans == null || w.length() < ans.length())) ans = w;
        }
        return ans;
    }
}

